const body = $json.body || $json;
let functionName = "";
let functionArgs = {};
let toolCallId = "";
let source = "unknown";

// ----------------------
// VAPI
// ----------------------
if (
  body.message &&
  body.message.toolCalls &&
  body.message.toolCalls.length > 0
) {
  const tool = body.message.toolCalls[0];
  functionName = tool.function?.name || "";
  functionArgs = tool.function?.arguments || {};
  toolCallId = tool.id || "";
  source = "vapi";
}
// ----------------------
// ElevenLabs
// ----------------------
else if (
  body.tool_calls &&
  body.tool_calls.length > 0
) {
  const tool = body.tool_calls[0];
  functionName = tool.name || "";
  functionArgs = tool.parameters || {};
  toolCallId = tool.id || "";
  source = "elevenlabs";
}

// Some platforms deliver arguments as a JSON string — parse defensively.
if (typeof functionArgs === "string") {
  try { functionArgs = JSON.parse(functionArgs); } catch (e) { functionArgs = {}; }
}

// ----------------------
// Fallback if nothing matched
// ----------------------
if (!functionName) {
  functionName = "fallback";
}

return [
  {
    json: {
      source,
      functionName,
      functionArgs,
      toolCallId
    }
  }
];

