const cfg = $json;
const args = cfg.functionArgs || {};
const slotDuration = (cfg.calendar && cfg.calendar.slotDuration) || 60;
const zone = 'Asia/Kolkata';

function parseTime(t) {
  if (t === undefined || t === null) return null;
  let s = String(t).trim().toLowerCase();
  if (!s) return null;
  let m = s.match(/^(\d{1,2}):(\d{2})\s*(am|pm)?$/);
  if (m) {
    let h = parseInt(m[1], 10);
    let min = parseInt(m[2], 10);
    if (m[3] === 'pm' && h < 12) h += 12;
    if (m[3] === 'am' && h === 12) h = 0;
    return { h: h, min: min };
  }
  m = s.match(/^(\d{1,2})\s*(am|pm)$/);
  if (m) {
    let h = parseInt(m[1], 10);
    if (m[2] === 'pm' && h < 12) h += 12;
    if (m[2] === 'am' && h === 12) h = 0;
    return { h: h, min: 0 };
  }
  m = s.match(/^(\d{1,2})$/);
  if (m) {
    return { h: parseInt(m[1], 10), min: 0 };
  }
  return null;
}

let startDT = null;
// Accept combined date-time under any of the field names platforms send (book or reschedule).
const combined = args.requested_datetime || args.new_requested_datetime || args.new_date_time || args.datetime || args.new_datetime || null;
// Accept separate date/time for both booking (requested_*) and reschedule (new_requested_*) tools.
const datePart = args.requested_date || args.new_requested_date || args.new_date || null;
const timePart = args.requested_time || args.new_requested_time || args.new_time || null;
if (combined) {
  startDT = DateTime.fromISO(String(combined), { zone: zone });
} else if (datePart) {
  const tp = parseTime(timePart);
  if (tp) {
    startDT = DateTime.fromISO(String(datePart), { zone: zone }).set({ hour: tp.h, minute: tp.min, second: 0, millisecond: 0 });
  }
}

const slotValid = !!(startDT && startDT.isValid);

const out = {
  source: cfg.source,
  functionName: cfg.functionName,
  functionArgs: args,
  toolCallId: cfg.toolCallId,
  calendar: cfg.calendar,
  slotDuration: slotDuration,
  slotValid: slotValid,
  slotStartISO: null,
  slotEndISO: null,
  slotStartLocalISO: null,
  slotEndLocalISO: null,
  slotSpokenTime: null,
  slotSpokenDate: null
};

if (slotValid) {
  const endDT = startDT.plus({ minutes: slotDuration });
  out.slotStartISO = startDT.toUTC().toISO();
  out.slotEndISO = endDT.toUTC().toISO();
  out.slotStartLocalISO = startDT.toISO();
  out.slotEndLocalISO = endDT.toISO();
  out.slotSpokenTime = startDT.toFormat('h:mm a');
  out.slotSpokenDate = startDT.toFormat('cccc, LLLL d');
}

return [{ json: out }];

const input = $input.first().json;
const toolCallId = $('Parse Request').first().json.toolCallId;

let resultText = "";

if (input.id) {
  const start = new Date(input.start.dateTime);
  const formatted = start.toLocaleString('en-IN', {
