    hour: 'numeric', minute: '2-digit', hour12: true,
    timeZone: 'Asia/Kolkata'
  });
  resultText = "Your appointment is confirmed for " + formatted + ".";
} else {
  resultText = "Sorry, there was an error booking your appointment. Please try again.";
}

return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: resultText
      }
    ]
  }
}];

