const items = $input.all();
const args = $('Parse Request').first().json.functionArgs;

const callerPhone = (args.customer_phone || args.phone || '').replace(/\D/g, '');
const callerName = (args.customer_name || args.full_name || '').toLowerCase().trim();

const matches = items.filter(item => {
  if (!item.json || !item.json.id) return false;
  const desc = (item.json.description || '').replace(/\D/g, '');
  const summary = (item.json.summary || '').toLowerCase();

  const phoneMatch = callerPhone && callerPhone.length >= 5 && desc.includes(callerPhone);
  const nameMatch = callerName && summary.includes(callerName);

  return phoneMatch || nameMatch;
});

// Prefer the soonest upcoming matching appointment.
matches.sort((a, b) => {
  const sa = (a.json.start && a.json.start.dateTime) || '';
  const sb = (b.json.start && b.json.start.dateTime) || '';
  return sa < sb ? -1 : sa > sb ? 1 : 0;
});

return [{
  json: {
    matchCount: matches.length,
    matches: matches.map(m => m.json)
  }
}];

const events = $input.all().map(i => i.json).filter(e => e && e.id);
const ownId = $('Find Matching Appointment1').first().json.matches[0].id;
const conflicts = events.filter(e => e.id !== ownId);
return [{ json: { free: conflicts.length === 0, toolCallId: $('Parse Request').first().json.toolCallId } }];

