const items = $input.all();
const args = $('Parse Request').first().json.functionArgs;
const callerPhone = (args.customer_phone || args.phone || '').replace(/\D/g, '');
const callerName = (args.customer_name || args.full_name || '').toLowerCase().trim();

const matches = items.filter(item => {
  if (!item.json || !item.json.id) return false;
  const desc = (item.json.description || '').replace(/\D/g, '');
  const summary = (item.json.summary || '').toLowerCase();
  const phoneMatch = callerPhone && callerPhone.length >= 5 && desc.includes(callerPhone);
  const nameMatch = callerName && summary.includes(callerName);
  return phoneMatch || nameMatch;
});

matches.sort((a, b) => {
  const sa = (a.json.start && a.json.start.dateTime) || '';
  const sb = (b.json.start && b.json.start.dateTime) || '';
  return sa < sb ? -1 : sa > sb ? 1 : 0;
});

return [{
  json: {
    matchCount: matches.length,
    matches: matches.map(m => ({ id: m.json.id, summary: m.json.summary, start: (m.json.start && m.json.start.dateTime) || null }))
  }
}];

const toolCallId = $('Parse Request').first().json.toolCallId;
const matchCount = $json.matchCount;

let msg;
if (matchCount === 0) {
  msg = "I couldn't find an appointment under that name or number. Could you tell me the date it's booked for?";
} else {
  msg = "I found a few appointments that might match. Could you tell me the date of the one you'd like to cancel?";
}

return [{ json: { results: [{ toolCallId: toolCallId, result: msg }] } }];

const cfg = $('Parse Request').first().json;
const tag = $input.first().json;
const args = cfg.functionArgs || {};

const actionMap = {
  book_appointment: 'Booking',
  reschedule_appointment: 'Reschedule',
  cancel_appointment: 'Cancellation',
  check_availability: 'Availability Check',
  answer_question: 'Question'
};
const action = actionMap[cfg.functionName] || 'Other';

const callerName = args.customer_name || args.full_name || '';
const callerPhone = args.customer_phone || args.phone || '';
const service = args.service || '';
const requestedTime = [cfg.slotSpokenDate, cfg.slotSpokenTime].filter(Boolean).join(' at ');
const platform = cfg.source || 'unknown';
const outcome = tag.logOutcome || 'unknown';
const important = !!tag.important;
const timestamp = DateTime.now().setZone('Asia/Kolkata').toFormat('yyyy-LL-dd HH:mm:ss');

const emoji = outcome === 'booked' ? '\uD83D\uDFE2' : outcome === 'cancelled' ? '\uD83D\uDD34' : outcome === 'rescheduled' ? '\uD83D\uDD04' : '\u2139\uFE0F';
const slackText = emoji + ' *' + action + '* — ' + (callerName || 'Unknown') + (callerPhone ? ' (' + callerPhone + ')' : '') + (service ? ' • ' + service : '') + (requestedTime ? ' • ' + requestedTime : '') + ' • via ' + platform;

return [{ json: {
  timestamp: timestamp,
  action: action,
  outcome: outcome,
  caller_name: callerName,
  caller_phone: callerPhone,
  service: service,
  requested_time: requestedTime,
  platform: platform,
  execution_id: $execution.id,
  important: important,
  slackText: slackText
} }];
